      backgroundColor: '#1890ff',
      transform: 'none',
      top: '39%',
      border: 0,
    },
    ...theme.applyStyles('light', {
      color: 'rgba(0,0,0,.85)',
    }),
  },
  ...theme.applyStyles('light', {
    borderColor: '#f0f0f0',
    color: 'rgba(0,0,0,.85)',
  }),
